UPDATE board
SET board_like_count = board_like_count + 1
WHERE board_id = #{boardId}

UPDATE board
SET board_view_count = board_view_count + 1
WHERE board_id = #{boardId}

UPDATE board 
SET board_title = #{boardTitle}, 
    board_content = #{boardContent}
WHERE board_id = #{boardId}

UPDATE board_adopt 
SET board_adopt_done = #{boardAdoptDone}
WHERE board_id = #{boardId}
